          flow:      false,  // true when trench tile has active flow this tick
          depth:     0,      // trench depth 0..1 (1 = freshly dug); siltation lowers it over time
          crop:      CropType.NONE,
          cropAge:   0,
          cropReady: false,
          stress:    '',
          variation: pattern
